//! Proves that the stylesheets generated by `mp-theme` work in the installed GTK and
//! libadwaita. Each built-in theme, the example theme and a deliberately hostile theme
//! is loaded into a `gtk::CssProvider`, and any parsing error fails the run.
//! The CSS features `docs/themes.md` promises to theme authors are checked the same way.
//!
//! Every theme is then shown in the light and the dark scheme, switched through
//! libadwaita's `StyleManager` exactly like the app does, and the colours it sets
//! (through `var()` and `color-mix()`) are read back from real widgets and checked for
//! readable contrast.
//!
//! libadwaita only switches the scheme of its own stylesheet, so a theme provider has
//! to follow `StyleManager:dark` itself. [`follow_style_manager`] shows how, with
//! `Theme::to_css_for_scheme`, which works on every GTK version the app supports. On
//! GTK 4.20 and later, `Theme::to_css` (both schemes under media queries) must parse
//! too.
//!
//! GTK needs a display. A headless Broadway server works:
//!
//! ```text
//! gtk4-broadwayd :45 &
//! GDK_BACKEND=broadway BROADWAY_DISPLAY=:45 cargo run -p mp-theme --example check_css
//! ```

use std::cell::RefCell;
use std::path::Path;
use std::process::ExitCode;
use std::rc::Rc;
use std::time::Duration;

use adw::prelude::*;
use gtk::{CssProvider, gdk, glib};
use mp_theme::{Palette, Theme, ThemeManifest, ThemeSource};

/// WCAG AA minimum for body text.
const TEXT_CONTRAST: f64 = 4.5;
const HOSTILE_ID: &str = "hostile";

/// Probe labels copy a CSS variable into their `color` so it can be read back.
const PROBES: [&str; 6] = [
    "--accent-bg-color",
    "--accent-color",
    "--window-bg-color",
    "--window-fg-color",
    "--mp-player-bar-bg-color",
    "--mp-window-bg-color",
];

fn main() -> ExitCode {
    if let Err(err) = adw::init() {
        eprintln!("Could not initialise libadwaita (is a display available?): {err}");
        return ExitCode::FAILURE;
    }
    let Some(display) = gdk::Display::default() else {
        eprintln!("No default display");
        return ExitCode::FAILURE;
    };
    println!(
        "GTK {}.{}.{}, libadwaita {}.{}.{}",
        gtk::major_version(),
        gtk::minor_version(),
        gtk::micro_version(),
        adw::major_version(),
        adw::minor_version(),
        adw::micro_version()
    );

    let themes = match themes_to_check() {
        Ok(themes) => themes,
        Err(message) => {
            eprintln!("{message}");
            return ExitCode::FAILURE;
        }
    };
    let probes = Probes::new(&display);

    let mut failures = check_documented_features(&display);
    let status = if failures.is_empty() { "ok" } else { "FAILED" };
    println!("{:<10} {status}", "features");

    for theme in &themes {
        let problems = check_theme(&display, &probes, theme);
        let status = if problems.is_empty() { "ok" } else { "FAILED" };
        println!("{:<10} {status}", theme.id);
        failures.extend(
            problems
                .into_iter()
                .map(|problem| format!("{}: {problem}", theme.id)),
        );
    }

    if failures.is_empty() {
        println!(
            "All {} stylesheets parsed and resolved correctly in both schemes.",
            themes.len()
        );
        ExitCode::SUCCESS
    } else {
        for failure in &failures {
            eprintln!("{failure}");
        }
        ExitCode::FAILURE
    }
}

fn themes_to_check() -> Result<Vec<Theme>, String> {
    let mut themes = mp_theme::builtin_themes();
    let example = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../examples/themes/sunset");
    let sunset = mp_theme::load_theme(&example)
        .map_err(|err| format!("Example theme failed to load: {err}"))?;
    themes.push(sunset);
    themes.push(hostile_theme());
    Ok(themes)
}

/// CSS that `docs/themes.md` promises works in `style.css`: `var()`, `color-mix()`,
/// `alpha()` and `@media (prefers-color-scheme: ...)`. Each must parse and resolve on
/// a real widget, in both schemes.
const DOCUMENTED_FEATURES_CSS: &str = "
:root { --check-base: #336699; }
@media (prefers-color-scheme: dark) { :root { --check-base: #99bbdd; } }
.check-var { color: var(--check-base); }
.check-mix { color: color-mix(in srgb, var(--check-base) 40%, transparent); }
.check-alpha { color: alpha(#336699, 0.5); }
";

fn check_documented_features(display: &gdk::Display) -> Vec<String> {
    let mut theme = hostile_theme();
    theme.manifest = ThemeManifest::default();
    theme.extra_css = Some(DOCUMENTED_FEATURES_CSS.to_owned());
    let window = gtk::Window::new();
    let column = gtk::Box::new(gtk::Orientation::Vertical, 0);
    let labels = ["check-var", "check-mix", "check-alpha"].map(|class| {
        let label = gtk::Label::new(Some(class));
        label.add_css_class(class);
        column.append(&label);
        label
    });
    window.set_child(Some(&column));
    window.present();

    let mut problems = Vec::new();
    for (dark, base) in [(false, "#336699"), (true, "#99bbdd")] {
        let (provider, errors) = load_stylesheet(&theme.to_css_for_scheme(dark));
        problems.extend(errors);
        gtk::style_context_add_provider_for_display(
            display,
            &provider,
            gtk::STYLE_PROVIDER_PRIORITY_APPLICATION + 2,
        );
        settle();
        let base = gdk::RGBA::parse(base).expect("valid colour");
        let [var, mix, alpha] = labels.each_ref().map(|label| label.color());
        let mixed = base.with_alpha(0.4);
        let expected_alpha = gdk::RGBA::new(0.2, 0.4, 0.6, 0.5);
        for (name, actual, expected) in [
            ("var()", var, base),
            ("color-mix()", mix, mixed),
            ("alpha()", alpha, expected_alpha),
        ] {
            if !same_color(&actual, &expected) {
                problems.push(format!(
                    "{name} resolved to {actual} in the {} scheme, expected {expected}",
                    scheme_name(dark)
                ));
            }
        }
        gtk::style_context_remove_provider_for_display(display, &provider);
    }
    window.destroy();
    problems
        .into_iter()
        .map(|problem| format!("features: {problem}"))
        .collect()
}

/// A provider that records every parsing error, from every load.
fn recording_provider() -> (CssProvider, Rc<RefCell<Vec<String>>>) {
    let provider = CssProvider::new();
    let problems = Rc::new(RefCell::new(Vec::new()));
    provider.connect_parsing_error({
        let problems = problems.clone();
        move |_, section, error| {
            problems
                .borrow_mut()
                .push(format!("parse error at {}: {error}", section.to_str()));
        }
    });
    (provider, problems)
}

/// Loads `css` into a new provider, collecting every parsing error.
fn load_stylesheet(css: &str) -> (CssProvider, Vec<String>) {
    let (provider, problems) = recording_provider();
    provider.load_from_string(css);
    let problems = problems.take();
    (provider, problems)
}

fn check_theme(display: &gdk::Display, probes: &Probes, theme: &Theme) -> Vec<String> {
    let (provider, parse_errors) = recording_provider();
    gtk::style_context_add_provider_for_display(
        display,
        &provider,
        gtk::STYLE_PROVIDER_PRIORITY_APPLICATION + 1,
    );
    let style_manager = adw::StyleManager::default();
    let following = follow_style_manager(&style_manager, &provider, theme.clone());
    let mut problems = Vec::new();
    for (scheme, dark, overrides) in [
        (adw::ColorScheme::ForceLight, false, &theme.manifest.light),
        (adw::ColorScheme::ForceDark, true, &theme.manifest.dark),
    ] {
        style_manager.set_color_scheme(scheme);
        settle();
        let name = scheme_name(dark);
        if style_manager.is_dark() != dark {
            problems.push(format!("{name}: libadwaita did not switch scheme"));
        }
        let resolved = probes.read();
        problems.extend(
            check_colors(theme, overrides, &resolved)
                .into_iter()
                .map(|problem| format!("{name}: {problem}")),
        );
    }
    style_manager.disconnect(following);
    gtk::style_context_remove_provider_for_display(display, &provider);
    problems.extend(parse_errors.take());

    if gtk::check_version(4, 20, 0).is_none() {
        let (_, errors) = load_stylesheet(&theme.to_css());
        problems.extend(errors.into_iter().map(|error| format!("to_css: {error}")));
    }
    problems
}

/// Keeps `provider` holding `theme`'s stylesheet for libadwaita's current light/dark
/// state, whether the user, the system or a theme chose it.
fn follow_style_manager(
    style_manager: &adw::StyleManager,
    provider: &CssProvider,
    theme: Theme,
) -> glib::SignalHandlerId {
    let provider = provider.clone();
    let reload = move |style_manager: &adw::StyleManager| {
        provider.load_from_string(&theme.to_css_for_scheme(style_manager.is_dark()));
    };
    reload(style_manager);
    style_manager.connect_dark_notify(reload)
}

fn scheme_name(dark: bool) -> &'static str {
    if dark { "dark" } else { "light" }
}

/// Compares the resolved colours with what the theme asked for.
fn check_colors(
    theme: &Theme,
    overrides: &Palette,
    resolved: &[gdk::RGBA; PROBES.len()],
) -> Vec<String> {
    let [
        accent,
        accent_text,
        window,
        window_text,
        player_bar,
        translucent_window,
    ] = resolved;
    let shared = &theme.manifest.colors;
    let pick = |field: fn(&Palette) -> &Option<String>| {
        field(overrides)
            .clone()
            .or_else(|| field(shared).clone())
            .and_then(|value| gdk::RGBA::parse(value.as_str()).ok())
    };
    let mut problems = Vec::new();

    // With `panel_opacity` the player bar colour is mixed with transparency.
    let panel_opacity = theme
        .manifest
        .effects
        .panel_opacity
        .filter(|opacity| opacity.is_finite())
        .map_or(1.0, |opacity| opacity.clamp(0.5, 1.0));
    let expectations = [
        ("--accent-bg-color", accent, pick(|p| &p.accent)),
        ("--window-bg-color", window, pick(|p| &p.window_bg)),
        (
            "--mp-player-bar-bg-color",
            player_bar,
            pick(|p| &p.player_bar_bg).map(|color| color.with_alpha(color.alpha() * panel_opacity)),
        ),
    ];
    for (variable, actual, expected) in expectations {
        let Some(expected) = expected else {
            continue;
        };
        if !same_color(actual, &expected) {
            problems.push(format!(
                "{variable} resolved to {actual}, expected {expected}"
            ));
        }
    }

    let wants_translucency = theme
        .manifest
        .effects
        .window_opacity
        .is_some_and(|opacity| opacity < 1.0);
    if wants_translucency && translucent_window.alpha() >= 0.999 {
        problems.push(format!(
            "--mp-window-bg-color should be translucent, got {translucent_window}"
        ));
    }

    if theme.id != HOSTILE_ID {
        for (label, foreground) in [("window text", window_text), ("accent text", accent_text)] {
            let ratio = contrast(foreground, window);
            if ratio < TEXT_CONTRAST {
                problems.push(format!(
                    "{label} {foreground} on {window} has contrast {ratio:.2}, needs {TEXT_CONTRAST}"
                ));
            }
        }
    }
    problems
}

/// A window of labels, one per entry in [`PROBES`].
struct Probes {
    window: gtk::Window,
    labels: Vec<gtk::Label>,
}

impl Probes {
    fn new(display: &gdk::Display) -> Self {
        let css: String = PROBES
            .iter()
            .enumerate()
            .map(|(index, variable)| format!(".probe-{index} {{ color: var({variable}); }}\n"))
            .collect();
        let (provider, problems) = load_stylesheet(&css);
        assert!(problems.is_empty(), "probe CSS: {problems:?}");
        gtk::style_context_add_provider_for_display(
            display,
            &provider,
            gtk::STYLE_PROVIDER_PRIORITY_APPLICATION + 2,
        );

        let window = gtk::Window::new();
        let column = gtk::Box::new(gtk::Orientation::Vertical, 0);
        let labels = (0..PROBES.len())
            .map(|index| {
                let label = gtk::Label::new(Some("probe"));
                label.add_css_class(&format!("probe-{index}"));
                column.append(&label);
                label
            })
            .collect();
        window.set_child(Some(&column));
        window.present();
        Self { window, labels }
    }

    fn read(&self) -> [gdk::RGBA; PROBES.len()] {
        std::array::from_fn(|index| self.labels[index].color())
    }
}

impl Drop for Probes {
    fn drop(&mut self) {
        self.window.destroy();
    }
}

/// Lets GTK and libadwaita apply style changes.
fn settle() {
    let context = glib::MainContext::default();
    for _ in 0..50 {
        while context.iteration(false) {}
        std::thread::sleep(Duration::from_millis(2));
    }
}

fn same_color(a: &gdk::RGBA, b: &gdk::RGBA) -> bool {
    let close = |x: f32, y: f32| (x - y).abs() < 1.5 / 255.0;
    close(a.red(), b.red())
        && close(a.green(), b.green())
        && close(a.blue(), b.blue())
        && close(a.alpha(), b.alpha())
}

/// WCAG 2 contrast ratio, ignoring transparency.
fn contrast(a: &gdk::RGBA, b: &gdk::RGBA) -> f64 {
    let luminance = |color: &gdk::RGBA| {
        let channel = |c: f32| {
            let c = f64::from(c);
            if c <= 0.04045 {
                c / 12.92
            } else {
                ((c + 0.055) / 1.055).powf(2.4)
            }
        };
        0.2126 * channel(color.red())
            + 0.7152 * channel(color.green())
            + 0.0722 * channel(color.blue())
    };
    let (la, lb) = (luminance(a), luminance(b));
    (la.max(lb) + 0.05) / (la.min(lb) + 0.05)
}

/// A theme full of edge cases: valid but unusual colour syntaxes, invalid values
/// that must be dropped, extreme numbers and text that tries to escape the CSS.
fn hostile_theme() -> Theme {
    let text = |value: &str| Some(value.to_owned());
    let mut manifest = ThemeManifest {
        name: "Hostile */ window { color: red; } /*".into(),
        author: "\"; } *".into(),
        font_family: text(r#"Fancy "Quoted" Font, Back\slash, 'Noto Sans', monospace"#),
        ..ThemeManifest::default()
    };
    manifest.colors.accent = text("hsl(210deg 40% 50%)");
    manifest.colors.accent_fg = text("#abcd");
    manifest.colors.border = text("rgb(10 20 30 / 50%)");
    manifest.colors.hires_badge = text("hsla(40, 80%, 50%, 0.9)");
    manifest.light.window_bg = text("#11223344");
    manifest.light.window_fg = text("rgba(1, 2, 3, 0.8)");
    manifest.light.sidebar_bg = text("red; } * { color: red");
    manifest.dark.window_bg = text("#123");
    manifest.dark.player_bar_bg = text("url(file:///etc/passwd)");
    manifest.dark.card_bg = text("var(--evil)");
    manifest.shape.window_radius = Some(u32::MAX);
    manifest.shape.spacing = Some(u32::MAX);
    manifest.effects.window_opacity = Some(-3.0);
    manifest.effects.panel_opacity = Some(f32::INFINITY);
    manifest.effects.cover_shadow = Some(7.0);
    Theme {
        id: HOSTILE_ID.into(),
        manifest,
        source: ThemeSource::Builtin,
        extra_css: Some(HOSTILE_STYLESHEET.to_owned()),
        stylesheet_problem: None,
    }
}

/// Valid CSS that is awkward to resolve per scheme: braces and `@media` inside
/// comments and strings, nested and unrelated media queries.
const HOSTILE_STYLESHEET: &str = r#"
/* } { @media (prefers-color-scheme: dark) { */
@MEDIA (Prefers-Color-Scheme: DARK) {
  .hostile-a { color: #ffffff; } /* } */
  @media (prefers-color-scheme: light) { .hostile-b { color: #000000; } }
}
@media (prefers-color-scheme: light) { .hostile-c { font-family: "}{ @media"; } }
.hostile-d { font-family: '@media (prefers-color-scheme: dark) {'; }
"#;
